function createPartVisual(part) {
  switch (part.type) {
    case "command":
      return buildCommandPod(part);
    case "fuel":
      return buildFuelTank(part);
    case "engine":
      return buildEngine(part);
    case "booster":
      return buildBooster(part);
    case "decoupler":
      return buildDecoupler(part);
    case "parachute":
      return buildParachute(part);
    case "aero":
      return buildAeroFin(part);
    case "rcs":
      return buildRCSBlock(part);
    case "solar":
      return buildSolarPanel(part);
    case "landing":
      return buildLandingLeg(part);
    case "science":
      return buildScienceInstrument(part);
    case "antenna":
      return buildCommAntenna(part);
    case "adapter":
      return buildAdapter(part);
    case "structural":
      return buildStructuralTube(part);
    case "utility":
      return buildDockingPort(part);
    case "fusion":
      return buildFusionReactor(part);
    case "warp":
      return buildWarpDrive(part);
    case "radiator":
      return buildRadiator(part);
    case "mining":
      return buildMiningRig(part);
    case "colony":
      return buildColonyModule(part);
    case "antimatter":
      return buildAntimatterEngine(part);
    case "plasma":
      return buildPlasmaEngine(part);
    default:
      return buildScienceInstrument(part);
  }
}
function texBrushedMetal(type, size = 1024) {
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");
  const img = ctx.createImageData(size, size);
  const d = img.data;
  const pal = {
    aluminum: [198, 202, 208],
    titanium: [152, 150, 147],
    copper: [186, 118, 55],
    inconel: [115, 118, 122],
    steel: [135, 138, 142],
    white: [238, 239, 241],
    dark: [42, 44, 50]
  };
  const [br, bg, bb] = pal[type];
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const i = (y * size + x) * 4;
      const dirVar = TextureFactory.fbm(x * 2e-3, y * 0.08, 3, 0.4, 2) * 0.3;
      const streak = TextureFactory.fbm(x * 0.08, y * (4e-3 + dirVar), 5, 0.5, 2);
      const grain = TextureFactory.fbm(x * 0.4, y * 0.4, 3, 0.4, 2.5);
      const oxPatch = TextureFactory.fbm(x * 0.015, y * 0.015, 3, 0.5, 2);
      const oxideLayer = TextureFactory.fbm(x * 8e-3, y * 0.012, 4, 0.5, 2.2);
      const v = (streak * 0.4 + grain * 0.15 - 0.28) * 85;
      const ox = oxPatch * 12;
      let oR = 0, oG = 0, oB = 0;
      if (type === "copper") {
        oR = oxideLayer * 25;
        oG = oxideLayer * 10;
        oB = -oxideLayer * 5;
      } else if (type === "titanium") {
        oR = oxideLayer * 15;
        oG = oxideLayer * 8;
        oB = oxideLayer * 20;
      } else if (type === "steel") {
        oR = oxideLayer * 10;
        oG = oxideLayer * 6;
        oB = -oxideLayer * 3;
      }
      d[i] = Math.max(0, Math.min(255, br + v + ox + oR));
      d[i + 1] = Math.max(0, Math.min(255, bg + v + ox * 0.7 + oG));
      d[i + 2] = Math.max(0, Math.min(255, bb + v + ox * 0.4 + oB));
      d[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  const tex = new CanvasTexture(canvas);
  tex.colorSpace = SRGBColorSpace;
  tex.wrapS = RepeatWrapping;
  tex.wrapT = RepeatWrapping;
  return tex;
}
