  const pumpCoverMat = new MeshStandardMaterial({ map: texBrushedMetal("aluminum", 256), color: 8947848, metalness: 0.8, roughness: 0.2 });
  const pumpCover = new Mesh(new CylinderGeometry(0.14, 0.14, 0.04, 20), pumpCoverMat);
