  const manifoldMat = new MeshStandardMaterial({ map: texBrushedMetal("steel", 256), color: 8947848, metalness: 0.75, roughness: 0.25 });
  const manifoldRing = new Mesh(new TorusGeometry(nozzleR * 0.36, 0.022, 10, 40), manifoldMat);
