        auto_circularize: "\u{1F916} \u81EA\u52A8\u9A7E\u9A76:\u81EA\u52A8\u5706\u5316",
        auto_rendezvous: "\u{1F916} \u81EA\u52A8\u9A7E\u9A76:\u81EA\u52A8\u4EA4\u4F1A"
